<script>
const canvas=document.getElementById('c');
const ctx=canvas.getContext('2d');
let w,h,dpr,particles=[];
const mouse={x:-9999,y:-9999,active:false};
const CFG={density:1/9000,min:45,max:130,link:128,mouseRadius:150};

function theme(){
  const cs=getComputedStyle(document.body);
  const g=v=>cs.getPropertyValue(v).trim();
  return {
    accent:g('--viz-accent')||'#5b8def',
    panel:g('--viz-panel')||'#0f1117',
    text:g('--viz-text')||'#e6e6e6',
    muted:g('--viz-muted')||'#8a8f98'
  };
}
let T=theme();

function resize(){
  dpr=Math.min(window.devicePixelRatio||1,2);
  w=window.innerWidth; h=window.innerHeight;
  canvas.width=w*dpr; canvas.height=h*dpr;
  canvas.style.width=w+'px'; canvas.style.height=h+'px';
  ctx.setTransform(dpr,0,0,dpr,0,0);
  T=theme();
  init();
}
function rand(a,b){return a+Math.random()*(b-a);}

function init(){
  const n=Math.min(CFG.max,Math.max(CFG.min,Math.floor(w*h*CFG.density)));
  particles=[];
  for(let i=0;i<n;i++){
    particles.push({x:Math.random()*w,y:Math.random()*h,vx:(Math.random()-.5)*.5,vy:(Math.random()-.5)*.5,r:rand(.6,2.4),a:rand(.25,.85),d:Math.random()});
  }
}

function step(){
  // motion trail
  ctx.globalAlpha=.2;
  ctx.fillStyle=T.panel;
  ctx.fillRect(0,0,w,h);
  ctx.globalAlpha=1;

  for(const p of particles){
    if(mouse.active){
      const dx=p.x-mouse.x,dy=p.y-mouse.y;
      const dd=Math.hypot(dx,dy);
      if(dd<CFG.mouseRadius && dd>0){
        const f=(1-dd/CFG.mouseRadius)*.7;
        p.vx+=(dx/dd)*f; p.vy+=(dy/dd)*f;
      }
    }
    p.vx*=.984; p.vy*=.984;
    p.vx+=(Math.random()-.5)*.025; p.vy+=(Math.random()-.5)*.025;
    const sp=Math.hypot(p.vx,p.vy), cap=1.4+p.d*.9;
    if(sp>cap){p.vx*=cap/sp; p.vy*=cap/sp;}
    p.x+=p.vx; p.y+=p.vy;
    if(p.x<0){p.x=0;p.vx=Math.abs(p.vx);}
    if(p.x>w){p.x=w;p.vx=-Math.abs(p.vx);}
    if(p.y<0){p.y=0;p.vy=Math.abs(p.vy);}
    if(p.y>h){p.y=h;p.vy=-Math.abs(p.vy);}
  }

  // links
  ctx.lineWidth=1;
  for(let i=0;i<particles.length;i++){
    for(let j=i+1;j<particles.length;j++){
      const a=particles[i],b=particles[j];
      const dd=Math.hypot(a.x-b.x,a.y-b.y);
      if(dd<CFG.link){
        const op=(1-dd/CFG.link)*.5;
        ctx.globalAlpha=op;
        ctx.strokeStyle=T.accent;
        ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();
        ctx.globalAlpha=1;
      }
    }
  }

  // particles
  for(const p of particles){
    const sz=p.r*(.55+p.d*.9);
    // glow
    const g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,sz*4.5);
    g.addColorStop(0,T.accent); g.addColorStop(1,'transparent');
    ctx.globalAlpha=.22*p.a; ctx.fillStyle=g;
    ctx.beginPath(); ctx.arc(p.x,p.y,sz*4.5,0,Math.PI*2); ctx.fill();
    // core
    ctx.globalAlpha=p.a; ctx.fillStyle=T.accent;
    ctx.beginPath(); ctx.arc(p.x,p.y,sz,0,Math.PI*2); ctx.fill();
    ctx.globalAlpha=1;
  }

